param([ValidateSet('BASELINE','REMEDIATION')][string]$Condition='BASELINE',[switch]$Finalize)
$ErrorActionPreference='Stop';$root=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path;$out=Join-Path $root 'backend\experiments\results\experiment-1-20\collector-preflight';$app='doeng-flux-exp119-fresh-first-20260803:latest';$appId='sha256:c2878d2847f80f3396a5cee5f02f1ec1ca3f7c14ceb8f49ea610d6e5fb6d9168';$mock='doeng-exp119-mock-frozen-20260803:latest';$mockId='sha256:2492f942c3931aa607293cf3da940e0e5aac0cfae91cbfe0ea88a893f0829ac1';$project='doeng-exp120-collector-preflight';$files=@('backend\docker-compose.experiment.yaml','backend\docker-compose.app-instance-t3-medium.yaml','backend\docker-compose.mock-headroom-4cpu.yaml','backend\docker-compose.http-pool-400.yaml','backend\docker-compose.mock-memory-headroom.yaml','backend\docker-compose.experiment-1-12-connection-attribution.yaml','backend\docker-compose.experiment-1-19-fresh-first-lifecycle.yaml');$args=@();foreach($f in $files){$args+=@('-f',(Join-Path $root $f))}
function J($v,$p){New-Item -ItemType Directory -Force -Path (Split-Path $p)|Out-Null;$v|ConvertTo-Json -Depth 8|Set-Content $p -Encoding UTF8};function WaitOk($url){$end=(Get-Date).AddSeconds(90);while((Get-Date)-lt$end){try{if((Invoke-WebRequest -UseBasicParsing $url -TimeoutSec 3).StatusCode-eq200){return}}catch{};Start-Sleep 1};throw "Health failed: $url"}
New-Item -ItemType Directory -Force -Path $out|Out-Null;if($Finalize){$b=Get-Content (Join-Path $out 'baseline.json') -Raw|ConvertFrom-Json;$r=Get-Content (Join-Path $out 'remediation.json') -Raw|ConvertFrom-Json;if($b.appImageId-ne$r.appImageId -or $b.mockImageId-ne$r.mockImageId -or $b.mockTag-ne$r.mockTag){throw 'Controlled image diff failed'};J ([ordered]@{ready=($b.collectorValid-and$r.collectorValid);sameImages=$true;allowedPolicyDiff=$true;warmup=0;k6=0;core=0;state='EXP120_READY_FOR_SIX_CORE_RUNS'}) (Join-Path $out 'finalize.json');'EXP120_READY_FOR_SIX_CORE_RUNS';exit 0}
$policy=if($Condition-eq'BASELINE'){@{s='FIFO';i='0';e='0'}}else{@{s='LIFO';i='3000';e='1000'}};$env:DOENG_EXP119_APP_IMAGE=$app;$env:DOENG_EXP119_MOCK_IMAGE=$mock;$env:DOENG_EXTERNAL_LEASING_STRATEGY=$policy.s;$env:DOENG_EXTERNAL_MAX_IDLE_TIME_MS=$policy.i;$env:DOENG_EXTERNAL_EVICTION_INTERVAL_MS=$policy.e
if((docker image inspect --format '{{.Id}}' $app).Trim()-ne$appId -or (docker image inspect --format '{{.Id}}' $mock).Trim()-ne$mockId){throw 'Frozen image mismatch'};$probe=Join-Path $out $Condition.ToLower();if(Test-Path $probe){Remove-Item $probe -Recurse -Force};New-Item -ItemType Directory -Force -Path $probe|Out-Null
try{docker compose -p $project @args up -d --force-recreate --no-build mariadb experiment-mock flux-corrected;if($LASTEXITCODE){throw 'Compose up failed'};WaitOk 'http://127.0.0.1:9001/actuator/health';WaitOk 'http://127.0.0.1:9100/health';$p=Start-Process powershell.exe -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-File',(Join-Path $PSScriptRoot 'collect-diagnostic-pool.ps1'),'-ManagementUrl','http://127.0.0.1:9001','-OutputPath',(Join-Path $probe 'pool-metrics.jsonl'),'-DurationSeconds','3','-IntervalMilliseconds','1000') -WindowStyle Hidden -PassThru;$p.WaitForExit();if($p.ExitCode){throw 'Collector process failed'};$lines=@(Get-Content (Join-Path $probe 'pool-metrics.jsonl')|Where-Object{$_.Trim()});if($lines.Count-lt2){throw 'Collector probe has fewer than two lines'};foreach($l in $lines){$null=$l|ConvertFrom-Json};$summary=Get-Content (Join-Path $probe 'pool-metrics.jsonl.summary.json') -Raw|ConvertFrom-Json;if($summary.failures-ne0){throw 'Collector probe failures'};J ([ordered]@{condition=$Condition;appImageId=$appId;mockTag=$mock;mockImageId=$mockId;policy=$policy;collectorValid=$true;lineCount=$lines.Count;failures=$summary.failures;warmup=0;k6=0;core=0}) (Join-Path $out "$($Condition.ToLower()).json");"$Condition COLLECTOR PREFLIGHT READY"}finally{docker compose -p $project @args down --remove-orphans|Out-Null}
